"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass, replace
from datetime import timedelta
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError


@dataclass(frozen=True)
class Policy:
    max_size: int | None = None
    max_age: timedelta | None = None
    naming: str = "numbered"
    offset: timedelta = timedelta(0)
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


KEYS = {"max_size", "max_age", "naming", "offset", "compress_after", "keep", "keep_days"}
_NUM = re.compile(r"[0-9]+")
_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)")
_DUR = re.compile(r"([0-9]+)([mhd])")
_OFF = re.compile(r"([+-])([0-9]{2}):([0-9]{2})")
_SEC = re.compile(r"\[([^\[\]]*)\]")


def _bad(msg):
    return DataError("policy", f"policy.ini: {msg}")


def _value(key, v):
    if key == "max_size":
        if v == "off":
            return None
        m = _SIZE.fullmatch(v)
        if not m:
            raise _bad(f"bad size {v!r}")
        return int(m[1]) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m[2].lower()]
    if key == "max_age":
        if v == "off":
            return None
        m = _DUR.fullmatch(v)
        if not m:
            raise _bad(f"bad duration {v!r}")
        n = int(m[1])
        return {"m": timedelta(minutes=n), "h": timedelta(hours=n), "d": timedelta(days=n)}[m[2]]
    if key == "naming":
        if v not in ("numbered", "dated"):
            raise _bad(f"bad naming {v!r}")
        return v
    if key == "offset":
        m = _OFF.fullmatch(v)
        if not m or int(m[2]) > 23 or int(m[3]) > 59:
            raise _bad(f"bad offset {v!r}")
        d = timedelta(hours=int(m[2]), minutes=int(m[3]))
        return -d if m[1] == "-" else d
    if not _NUM.fullmatch(v):
        raise _bad(f"bad number {v!r}")
    n = int(v)
    if key == "compress_after":
        return n
    if key == "keep":
        if n < 1:
            raise _bad("keep must be 1 or more")
        return n
    if key == "keep_days":
        return None if v == "off" else _fail_keep_days(v, n)
    raise _bad(key)


def _fail_keep_days(v, n):
    if n < 1:
        raise _bad("keep_days must be 1 or more")
    return n


def load(path: Path) -> dict:
    """Returns {"defaults": {...}, "streams": {name: {...}}} of raw-parsed settings."""
    defaults, per = {}, {}
    if path.exists():
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError) as e:
            raise _bad(str(e)) from None
        cur = None
        seen_def = False
        for raw in text.splitlines():
            line = raw.strip()
            if not line or line[0] in "#;":
                continue
            m = _SEC.fullmatch(line)
            if m:
                title = m[1]
                if title == "defaults":
                    if seen_def:
                        raise _bad("section twice")
                    seen_def = True
                    cur = defaults
                elif title.startswith("stream ") and streams.valid(title[7:]):
                    if title[7:] in per:
                        raise _bad("section twice")
                    cur = per[title[7:]] = {}
                else:
                    raise _bad(f"unknown section {title!r}")
                continue
            if cur is None or "=" not in line:
                raise _bad(f"bad line {line!r}")
            key, _, val = line.partition("=")
            key, val = key.strip(), val.strip()
            if key not in KEYS:
                raise _bad(f"unknown key {key!r}")
            if key in cur:
                raise _bad(f"key {key} twice")
            cur[key] = _value(key, val)
    return {"defaults": defaults, "streams": per}


def for_stream(doc: dict, name: str) -> Policy:
    p = replace(Policy(), **doc["defaults"])
    return replace(p, **doc["streams"].get(name, {}))
