"""rotate (docs/rotate.md)."""

import gzip
import os
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_ISO = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})", re.A)
_OLD = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}", re.A)
_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?", re.A)
_DATED = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?", re.A)


def parse_time(text, legacy=True):
    """A time with an offset (or the release 1.2 form, UTC); None when it is none."""
    if not isinstance(text, str):
        return None
    try:
        if _ISO.fullmatch(text):
            t = datetime.fromisoformat(text)
        elif legacy and _OLD.fullmatch(text):
            t = datetime.fromisoformat(text).replace(tzinfo=timezone.utc)
        else:
            return None
    except ValueError:
        return None
    if t.tzinfo is None or t.utcoffset() is None:
        return None
    return t


class Arch:
    def __init__(self, name, key, gz):
        self.name, self.key, self.gz = name, key, gz
        self.new = False
        self.time_raw = None
        self.final = None
        self.compress = False


def _archives(ctx, name, naming):
    d = streams.logs_dir(ctx.data)
    found = []
    prefix = f"{name}.log."
    if d.is_dir():
        for p in d.iterdir():
            n = p.name
            if not n.startswith(prefix) or not p.is_file():
                continue
            rest = n[len(prefix):]
            if naming == "numbered":
                m = _NUMBERED.fullmatch(rest)
                if m:
                    found.append(Arch(n, (int(m[1]),), bool(m[2])))
            else:
                m = _DATED.fullmatch(rest)
                if m:
                    try:
                        day = date.fromisoformat(m[1])
                    except ValueError:
                        continue
                    found.append(Arch(n, (day, int(m[2] or 1)), bool(m[3])))
    seen = set()
    for a in found:
        if a.key in seen:
            raise DataError("archives", f"{a.name}: two archives in the same place")
        seen.add(a.key)
    return found


def _sort(archs, naming):
    # newest first
    if naming == "numbered":
        return sorted(archs, key=lambda a: a.key)
    return sorted(archs, key=lambda a: a.key, reverse=True)


def _validate_state(doc, existing):
    for name, entry in doc["streams"].items():
        if name not in existing:
            continue
        bad = DataError("state", f"state.json: bad entry {name}")
        if "opened" in entry and parse_time(entry["opened"]) is None:
            raise bad
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict):
                raise bad
            for v in arch.values():
                if parse_time(v) is None:
                    raise bad
        if "rotations" in entry:
            r = entry["rotations"]
            if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                raise bad


def _first_line_time(path):
    try:
        with path.open("rb") as f:
            line = f.readline()
    except OSError:
        return None
    line = line.rstrip(b"\r\n") if b" " not in line else line
    head = line.split(b" ", 1)[0]
    try:
        return parse_time(head.decode("ascii"), legacy=False)
    except UnicodeDecodeError:
        return None


def run(ctx, names, dry_run, force):
    pol = policy.load(ctx.policy_path)
    doc = ctx.state
    active = set(streams.active(ctx.data))
    existing = active | set(pol["streams"])
    _validate_state(doc, existing)
    names = sorted(set(names)) if names else sorted(existing)
    for n in names:
        if n not in existing:
            raise Refused("unknown-stream", f"no stream {n}")

    now = ctx.now
    plans = []
    for name in names:
        pl = policy.for_stream(pol, name)
        plans.append((name, pl, _archives(ctx, name, pl.naming)))

    out = []
    n_rot = n_rem = n_comp = 0
    ops = []  # filesystem work
    new_entries = {}
    for name, pl, archs in plans:
        entry = doc["streams"].get(name, {})
        times = entry.get("archives", {}) if "archives" in entry else {}
        for a in archs:
            a.time_raw = times.get(a.name)
        log = streams.log_path(ctx.data, name)
        why = None
        size = log.stat().st_size if name in active else None
        if size is None:
            what = "no log"
        elif size == 0:
            what = "empty"
        elif force:
            what = "forced"
        elif pl.max_size is not None and size >= pl.max_size:
            what = "size"
        else:
            what = "not due"
            if pl.max_age is not None:
                opened = parse_time(entry["opened"]) if "opened" in entry else _first_line_time(log)
                if opened is not None and now - opened >= pl.max_age:
                    what = "age"
        rotated = what in ("forced", "size", "age")
        out.append(f"{name}: {'rotate (' + what + ')' if rotated else what}")

        newa = None
        if rotated:
            n_rot += 1
            if pl.naming == "numbered":
                key = (0,)
                nm = None
            else:
                day = now.astimezone(timezone(pl.offset)).date()
                ks = [a.key[1] for a in archs if a.key[0] == day]
                k = max(ks) + 1 if ks else 1
                key = (day, k)
                nm = f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")
            newa = Arch(nm, key, False)
            newa.new = True
            newa.time_raw = dates.stamp(now)
            archs.append(newa)
        if pl.naming == "numbered":
            order = sorted(archs, key=lambda a: (0,) if a.new else a.key)
            if newa:
                order = [newa] + sorted((a for a in archs if not a.new), key=lambda a: a.key)
        else:
            order = _sort(archs, "dated")
        keep, removed = [], []
        for pos, a in enumerate(order, 1):
            drop = pos > pl.keep
            if not drop and pl.keep_days is not None and a.time_raw is not None:
                t = parse_time(a.time_raw)
                if now - t >= timedelta(days=pl.keep_days):
                    drop = True
            (removed if drop else keep).append(a)
        lines = []
        for i, a in enumerate(keep, 1):
            a.compress = (not a.gz) and i > pl.compress_after
            gz = a.gz or a.compress
            if pl.naming == "numbered":
                a.final = f"{name}.log.{i}" + (".gz" if gz else "")
            else:
                base = a.name[:-3] if a.name.endswith(".gz") else a.name
                if a.new:
                    base = a.name
                a.final = base + (".gz" if gz else "")
            if a.compress:
                n_comp += 1
            if a.new:
                lines.append(f"  new {a.final}")
            elif a.final != a.name:
                lines.append(f"  {a.final} <- {a.name}")
            else:
                lines.append(f"  {a.name}")
        out.extend(lines)
        if newa and newa.name is None:
            # numbered: name before the run does not exist; only matters if removed
            newa.name = f"{name}.log.1"
        for a in removed:
            out.append(f"  remove {a.name}")
        n_rem += len(removed)
        ops.append((name, pl, log, keep, removed, newa, rotated))

        ent = {}
        if rotated:
            ent["opened"] = dates.stamp(now)
        elif "opened" in entry:
            ent["opened"] = entry["opened"]
        ent["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ent["archives"] = {a.final: a.time_raw for a in keep if a.time_raw is not None}
        new_entries[name] = ent
    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    d = streams.logs_dir(ctx.data)
    tmp = 0
    for name, pl, log, keep, removed, newa, rotated in ops:
        for a in removed:
            if not a.new:
                os.remove(d / a.name)
        staged = []
        for a in keep:
            tmp += 1
            t = d / f".logkeep-tmp-{tmp}"
            if a.new:
                raw = log.read_bytes()
                if a.compress:
                    raw = gzip.compress(raw, mtime=0)
                t.write_bytes(raw)
                log.write_bytes(b"")
            elif a.compress:
                t.write_bytes(gzip.compress((d / a.name).read_bytes(), mtime=0))
                os.remove(d / a.name)
            elif a.final != a.name:
                os.rename(d / a.name, t)
            else:
                continue
            staged.append((t, d / a.final))
        if newa and newa in removed:
            log.write_bytes(b"")
        for t, f in staged:
            os.replace(t, f)
    for name, ent in new_entries.items():
        doc["streams"][name] = ent
    state.save(ctx.state_path, doc)
    return out
